/* stat cards */
.kpi-wrap{width:100%;max-width:1000px}
.kpi-top{display:flex;align-items:center;justify-content:flex-end;margin-bottom:10px}
.kpi{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.kpi-c{background:var(--panel);border:1px solid var(--line);padding:18px 18px 16px;display:flex;flex-direction:column;gap:18px;min-width:0;transition:border-color .3s}
.kpi-c:hover{border-color:var(--icon-line)}
.kpi-c .lab{font-size:14px;font-weight:600}
.kpi-c .lab .per{color:var(--muted);font-weight:500}
.kpi-c .body{display:grid;grid-template-columns:auto 1fr;align-items:end;gap:14px}
.kpi-c .num{font-family:var(--mono);font-weight:700;font-size:30px;letter-spacing:-.6px;line-height:1.1;margin-bottom:10px}
.kpi-c .chart-r{position:relative;height:84px;min-width:0}
.kpi-c .spark{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.kpi-c .spark .tl{fill:none;stroke:var(--accent);stroke-width:1.75;vector-effect:non-scaling-stroke;transition:stroke .3s}
.kpi-c.down .spark .tl{stroke:var(--danger)}
.kpi-c .mk-line{position:absolute;top:0;bottom:0;width:0;border-left:1px dashed rgba(var(--fg-rgb),.22);transition:left .6s var(--ease)}
.kpi-c .mk-dot{position:absolute;width:8px;height:8px;margin:-4px 0 0 -4px;background:var(--accent);box-shadow:0 0 0 3px var(--panel);transition:left .6s var(--ease),top .6s var(--ease),background-color .3s}
.kpi-c.down .mk-dot{background:var(--danger)}
.kpi-c .mk-lab{position:absolute;transform:translate(-50%,-100%);margin-top:-10px;padding:1px 6px;font-family:var(--mono);font-weight:700;font-size:10px;color:var(--text);background:var(--chip);white-space:nowrap;transition:left .6s var(--ease),top .6s var(--ease)}

/* ---------- stat cards ---------- */
{
  const kpi = $('#kpi');
  const metrics = [
    { k:'Active users', vals:{ week:[1240, '+8%'], month:[4860, '+12%'], quarter:[13900, '+6%'] }, seed:6, suf:'' },
    { k:'First response', vals:{ week:[2.4, '-12%'], month:[2.9, '+4%'], quarter:[3.1, '+9%'] }, seed:7, dec:1, suf:' h' },
    { k:'Conversion', vals:{ week:[4.1, '+3%'], month:[3.9, '-2%'], quarter:[4.0, '+5%'] }, seed:8, dec:1, suf:'%' }
  ];
  const W = 200, H = 84, MARK = 5;
  kpi.innerHTML = metrics.map((m, i) => `<div class="kpi-c" data-i="${i}">
    <span class="lab">${m.k} <span class="per">/ <span class="per-t fade-swap">Week</span></span></span>
    <div class="body">
      <div><div class="num">0</div><span class="pill done"><i></i><span>+0</span></span></div>
      <div class="chart-r"><svg class="spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="kg${i}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-opacity=".2"/><stop offset="1" stop-opacity="0"/></linearGradient></defs><path class="ta" fill="url(#kg${i})"/><path class="tl"/></svg><span class="mk-line"></span><span class="mk-dot"></span><span class="mk-lab"></span></div>
    </div></div>`).join('');
  // a wavy trend that ends in the direction of the change, with a marked point
  function trend(seed, up){
    const r = rng(seed), pts = []; let v = up ? 58 : 30;
    for (let i = 0; i < 9; i++){ pts.push([i / 8 * W, v]); v += (up ? -1 : 1) * (3 + r() * 5) + (i % 2 ? 9 : -9) * r(); v = Math.max(14, Math.min(72, v)); }
    return pts;
  }
  function show(period, first){
    $$('.kpi-c', kpi).forEach((c, i) => {
      const m = metrics[i], [v, delta] = m.vals[period], up = !delta.startsWith('-');
      countTo(c.querySelector('.num'), v, { dec:m.dec, suf:m.suf, dur:first ? 1100 : 700 });
      setPill(c.querySelector('.pill'), up ? 'done' : 'fail', delta + ' vs last ' + period);
      swapText(c.querySelector('.per-t'), period[0].toUpperCase() + period.slice(1));
      c.classList.toggle('down', !up);
      const pts = trend(m.seed + period.length * 7, up), line = smooth(pts), path = c.querySelector('.tl'), area = c.querySelector('.ta');
      const paint = () => { path.setAttribute('d', line); area.setAttribute('d', line + ` L${W},${H} L0,${H} Z`); c.querySelectorAll('stop').forEach(st => st.setAttribute('stop-color', up ? '#ff850d' : '#ff5a5f')); };
      if (first || reduce) paint(); else { path.style.transition = area.style.transition = 'opacity .2s'; path.style.opacity = area.style.opacity = '0'; setTimeout(() => { paint(); path.style.opacity = area.style.opacity = '1'; }, 200); }
      const [mx, my] = pts[MARK], x = mx / W * 100 + '%', y = my / H * 100 + '%';
      c.querySelector('.mk-line').style.left = x;
      const dot = c.querySelector('.mk-dot'); dot.style.left = x; dot.style.top = y;
      const lab = c.querySelector('.mk-lab'); lab.style.left = x; lab.style.top = y; lab.textContent = delta.replace('+', '');
    });
  }
  segInit($('#kpi-seg'), v => show(v));
  whenSeen($('#c44'), () => { show('week', true); ambient('c44', 'pop'); });
}
